using System;using System.Linq;using System.Text.Json;using System.IO;using MotorwaysSim;
namespace MotorwaysSim {public sealed partial class TrafficWorld {public object GateDebug()=>new{retired=retiredConnectionConcrete.Select(e=>new{edge=new[]{e.Key.Item1.X,e.Key.Item1.Y,e.Key.Item2.X,e.Key.Item2.Y},credit=e.Value,users=Cars.Where(c=>UsesRetiredConnection(c,e.Key)).Select(c=>new{c.Id,c.Stage,c.RouteIndex,c.ReturnRoute})}),motorways=Motorways,inventory=Inventory,owners=carparkThroats.Select(x=>new{lot=x.Key.Item1,access=x.Key.Item2,owner=x.Value}),cars=Cars.Where(c=>c.Waiting>20).Select(c=>new{c.Id,c.ShopId,c.Stage,physical=PhysicalCarpark(c),current=c.CurrentLane.Key,c.RouteIndex,c.DistanceAlongLane,gates=c.Lanes.Skip(c.RouteIndex).Select(l=>new{l.Key,valid=TryCarparkGate(c,l,out int lot,out var access,out double distance),lot,access,distance})})};}}
class Inspect {static void Main(string[] a){var opt=new JsonSerializerOptions{IncludeFields=true,PropertyNameCaseInsensitive=true};var s=new CustomScenarioSession(JsonSerializer.Deserialize<CustomScenarioDefinition>(File.ReadAllText(a[0]),opt));var wall=System.Diagnostics.Stopwatch.StartNew();while(!s.Complete){if(wall.Elapsed.TotalSeconds>120)throw new Exception("120s diagnostic cap");s.AdvanceTick();}Console.WriteLine(JsonSerializer.Serialize(s.World.GateDebug(),opt));}}
